function flattenCampos() {
  const out = [];
  function processa(g, tituloTopo) {
    if (g.pares) {
      g.pares.forEach(p => {
        out.push({ key: p.mec, label: `${p.linha} — ${p.rotMec || 'Mecanizada'}`, grupo: tituloTopo, subgrupo: g.titulo || undefined });
        out.push({ key: p.man, label: `${p.linha} — ${p.rotMan || 'Manual'}`, grupo: tituloTopo, subgrupo: g.titulo || undefined });
      });
    }
    (g.extras || []).forEach(f => out.push({ ...f, grupo: tituloTopo, subgrupo: g.titulo || undefined }));
    (g.campos || []).forEach(f => out.push({ ...f, grupo: tituloTopo, subgrupo: g.titulo || undefined }));
  }
  GRUPOS.forEach(g => {
    if (g.subgrupos) g.subgrupos.forEach(sub => processa(sub, g.titulo));
    else processa(g, g.titulo);
  });
  return out;
}
const CAMPOS = flattenCampos();
const KEYS_REAJUSTE = CAMPOS.filter(f => !f.noReajuste && !f.texto).map(f => f.key).concat(['valorLocacao', 'faminValor']);
function todosCampos(itensCustom) {
  return (itensCustom && itensCustom.length) ? CAMPOS.concat(itensCustom) : CAMPOS;
}
function keysReajusteTotal(itensCustom) {
  const extras = (itensCustom || []).filter(f => !f.noReajuste && !f.texto).map(f => f.key);
  return extras.length ? KEYS_REAJUSTE.concat(extras) : KEYS_REAJUSTE;
}

