/* ---------- Helpers ---------- */
function novoCliente(padroes) {
  const p = padroes || PADROES_INICIAIS;
  const base = {
    id: 'cli_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    razaoSocial: '', cnpj: '', regime: 'Remessa', sala: '', grupoEconomico: '',
    numeroContrato: '', dataInicio: '', prazoMeses: p.prazoMeses ?? 12,
    dataDistrato: '', motivoDistrato: '',
    valorLocacao: 0,
    armazenagemPeriodicidade: p.armazenagemPeriodicidade || 'Quinzenal',
    seguroPeriodicidade: p.seguroPeriodicidade || 'Quinzenal',
    faminAplica: true, faminValor: p.faminValor ?? 4000, faminJustificativa: '',
    detalhes: '', criadoEm: new Date().toISOString(),
  };
  todosCampos(p.itensCustom).forEach(f => { base[f.key] = p[f.key] !== undefined ? p[f.key] : (f.valor !== undefined ? f.valor : (f.texto ? '' : 0)); });
  return base;
}

function statusDe(c) {
  if (c.dataDistrato) return 'INATIVO';
  if (c.numeroContrato && c.dataInicio) return 'ATIVO';
  return 'EM NEGOCIAÇÃO';
}

function vencimentoDe(c) {
  if (!c.dataInicio || !c.prazoMeses) return '';
  const d = new Date(c.dataInicio + 'T00:00:00');
  if (isNaN(d)) return '';
  d.setMonth(d.getMonth() + Number(c.prazoMeses));
  return d.toISOString().slice(0, 10);
}

function diasAte(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00');
  if (isNaN(d)) return null;
  return Math.ceil((d - new Date().setHours(0, 0, 0, 0)) / 86400000);
}

function alertaContrato(c) {
  if (statusDe(c) !== 'ATIVO') return null;
  const dias = diasAte(vencimentoDe(c));
  if (dias === null) return null;
  if (dias < 0) return { nivel: 'vencido', dias, texto: `Vencido há ${Math.abs(dias)} dia(s)` };
  if (dias <= 30) return { nivel: 'critico', dias, texto: `Vence em ${dias} dia(s)` };
  if (dias <= 60) return { nivel: 'aviso', dias, texto: `Vence em ${dias} dia(s)` };
  return null;
}

const ORDEM_STATUS = { 'ATIVO': 0, 'EM NEGOCIAÇÃO': 1, 'INATIVO': 2 };
function ordenar(list) {
  return [...list].sort((a, b) => {
    const d = ORDEM_STATUS[statusDe(a)] - ORDEM_STATUS[statusDe(b)];
    if (d !== 0) return d;
    return a.razaoSocial.localeCompare(b.razaoSocial, 'pt-BR');
  });
}

const money = v => (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const dataBR = s => s ? new Date(s + 'T00:00:00').toLocaleDateString('pt-BR') : '—';

/* ---------- Inputs ---------- */
const inp = {
  border: `1px solid ${C.silverLight}`, borderRadius: 6, padding: '8px 10px',
  fontFamily: "'Roboto Mono', monospace", fontSize: 13.5, color: C.text,
  outline: 'none', width: '100%', boxSizing: 'border-box', background: '#fff',
};

function Lbl({ children }) {
  return <span style={{
    textTransform: 'uppercase', fontSize: 10, letterSpacing: 0.3,
    fontFamily: "'Montserrat', sans-serif", fontWeight: 700, color: C.silver,
    display: 'block', marginBottom: 4, lineHeight: 1.3, minHeight: 26,
  }}>{children}</span>;
}

function Field({ label, children }) {
  return <label style={{ display: 'block' }}><Lbl>{label}</Lbl>{children}</label>;
}

/** Campo numérico: sem placeholder, seleciona tudo ao focar, vazio vira 0 ao sair. */
function Num({ value, onChange, onCommit, percent, disabled }) {
  const [txt, setTxt] = useState(value === 0 ? '0' : String(value ?? ''));
  const touched = useRef(false);
  useEffect(() => {
    if (!touched.current) setTxt(value === 0 ? '0' : String(value ?? ''));
  }, [value]);
  return (
    <input
      type="text" inputMode="decimal" disabled={disabled}
      style={{ ...inp, textAlign: 'right', background: disabled ? '#F1F4F8' : '#fff', color: disabled ? C.silver : C.text }}
      value={txt}
      onFocus={e => { touched.current = true; e.target.select(); }}
      onChange={e => { const v = e.target.value.replace(/[^0-9.,-]/g, ''); setTxt(v); }}
      onBlur={() => {
        touched.current = false;
        const n = parseFloat(txt.replace(/\./g, '').replace(',', '.'));
        const val = isNaN(n) ? 0 : n;
        setTxt(String(val));
        onChange(val);
        if (onCommit) onCommit(val);
      }}
    />
  );
}

function Txt({ value, onChange, disabled, mono }) {
  return <input type="text" disabled={disabled} value={value ?? ''}
    onChange={e => onChange(e.target.value)}
    style={{ ...inp, fontFamily: mono ? "'Roboto Mono', monospace" : "'Roboto', sans-serif", textAlign: 'left' }} />;
}

function Sel({ value, onChange, options, disabled }) {
  return <select value={value} disabled={disabled} onChange={e => onChange(e.target.value)}
    style={{ ...inp, fontFamily: "'Roboto', sans-serif" }}>
    {options.map(o => <option key={o.value ?? o} value={o.value ?? o}>{o.label ?? o}</option>)}
  </select>;
}

function Badge({ status }) {
  const m = {
    'ATIVO': { bg: '#E8F5E9', c: C.green },
    'INATIVO': { bg: '#FDECEA', c: C.red },
    'EM NEGOCIAÇÃO': { bg: '#FFF8E1', c: '#9A6B00' },
  }[status];
  return <span style={{
    background: m.bg, color: m.c, fontFamily: "'Montserrat', sans-serif", fontWeight: 700,
    fontSize: 10, textTransform: 'uppercase', padding: '4px 10px', borderRadius: 20, whiteSpace: 'nowrap',
  }}>{status}</span>;
}

function AlertaPill({ a }) {
  if (!a) return null;
  const cor = a.nivel === 'critico' || a.nivel === 'vencido' ? C.red : C.yellow;
  const bg = a.nivel === 'critico' || a.nivel === 'vencido' ? '#FDECEA' : '#FFF8E1';
  return <span style={{
    background: bg, color: cor, fontFamily: "'Montserrat', sans-serif", fontWeight: 700,
    fontSize: 9.5, padding: '3px 8px', borderRadius: 20, marginLeft: 6, whiteSpace: 'nowrap',
  }}>⚠ {a.texto}</span>;
}

const btn = (variant) => ({
  padding: '9px 18px', borderRadius: 8, fontFamily: "'Montserrat', sans-serif",
  fontWeight: 700, fontSize: 12.5, cursor: 'pointer', whiteSpace: 'nowrap',
  border: variant === 'ghost' ? `1px solid ${C.navy}` : 'none',
  background: variant === 'primary' ? C.orange : variant === 'dark' ? C.navy : '#fff',
  color: variant === 'ghost' ? C.navy : variant === 'secondary' ? C.text : '#fff',
  ...(variant === 'secondary' ? { border: `1px solid ${C.silverLight}` } : {}),
});

/* ---------- Formulário de Cliente ---------- */
